        $frMtx[$m.Groups[1].Value] = Get-Phases $seg
    }
}

Write-Host '=== THREE-SITE ANNOTATION CONSISTENCY (cc vs tsw vs mtx) ==='
$allFr = ($frTsw.Keys + $frCc.Keys + $frMtx.Keys | Sort-Object -Unique)
foreach ($fr in $allFr) {
    $a = @($frCc[$fr])  -join '/'
    $b = @($frTsw[$fr]) -join '/'
    $c = @($frMtx[$fr]) -join '/'
    $flag = if ($a -eq $b -and $b -eq $c) { 'OK  ' } else { 'DIFF' }
    Write-Host ("  {0} FR-{1}: cc[{2}] tsw[{3}] mtx[{4}]" -f $flag, $fr, $a, $b, $c)
}

# ---- Parse bdpv4: line -> phase (nearest preceding '## N. PhX:' header) ----
$bdLines = Get-Content $bd
$linePhase = New-Object string[] ($bdLines.Count)
$cur = $null
for ($i = 0; $i -lt $bdLines.Count; $i++) {
    $h = [regex]::Match($bdLines[$i], '^##\s+\d+\.\s+(Ph\d+):')
    if ($h.Success) { $cur = $h.Groups[1].Value }
    elseif ($bdLines[$i] -match '^##\s') { $cur = $null }  # non-phase section
    $linePhase[$i] = $cur
}

Write-Host ''
Write-Host '=== bdpv4 AC-TOKEN NAMING -> FR ANNOTATION COMPLETENESS ==='
Write-Host '(carve-outs: Ph8 re-execution; Ph6 for HubRestoreFromOlderBackup)'
$allAcs = $acToFr.Keys | Sort-Object
$mismatch = @()
$namedCount = 0
foreach ($ac in $allAcs) {
    for ($i = 0; $i -lt $bdLines.Count; $i++) {
        if ($bdLines[$i] -like "*$ac*" -and $linePhase[$i]) {
            $ph = $linePhase[$i]
            $namedCount++
            $fr = $acToFr[$ac]
            $ann = @($frTsw[$fr])
            $carve = ($ph -eq 'Ph8') -or ($ac -eq 'HubRestoreFromOlderBackup' -and $ph -eq 'Ph6')
            if ($ann -notcontains $ph -and -not $carve) {
                $mismatch += ("  MISMATCH: {0} named in {1} (bdpv4:{2}) but FR-{3} annotation=[{4}]" -f $ac, $ph, ($i+1), $fr, ($ann -join '/'))
            }
            elseif ($ann -notcontains $ph -and $carve) {
                Write-Host ("  carve-out: {0} named in {1} (bdpv4:{2}); FR-{3} annotation=[{4}] (allowed)" -f $ac, $ph, ($i+1), $fr, ($ann -join '/'))
            }
        }
    }
}
Write-Host ("  token-naming hits scanned: {0}" -f $namedCount)
if ($mismatch.Count -eq 0) {
    Write-Host '  RESULT: CLEAN - no FR annotation omits a phase whose bdpv4 section tokens one of its ACs.'
} else {
    Write-Host '  RESULT: MISMATCHES FOUND:'
    $mismatch | ForEach-Object { Write-Host $_ }
}

# ---- Confirm the six Plugin* diagnostic ACs are NOT tokened in any bdpv4 phase (carve-out basis) ----
Write-Host ''
Write-Host '=== Plugin* diagnostic AC tokens in bdpv4 (expect none; Ph7 binding is descriptive carve-out) ==='
$plugins = 'PluginEnrollmentDiagnostics','PluginRecoveryControls','PluginIdentityDiagnostics','PluginLeastPrivilegeDenial','PluginEffectBoundary','PluginEditingOwnership'
foreach ($p in $plugins) {
    $hits = Select-String -Path $bd -SimpleMatch -Pattern $p
    if ($hits) { foreach ($h in $hits) { Write-Host ("  TOKENED: {0} at bdpv4:{1}" -f $p, $h.LineNumber) } }
    else { Write-Host ("  absent : {0}" -f $p) }
}

# ---- Spot-check the 8 R2 finding codes remain present in the normative mapping ----
Write-Host ''
Write-Host '=== R2 finding spot-checks (error codes in stable failure mapping, current-contracts) ==='
foreach ($code in 'request_id_conflict','audit_id_conflict','waiting_local_work','already_applied') {
    $hits = Select-String -Path $cc -SimpleMatch -Pattern $code
    Write-Host ("  {0}: {1} occurrence(s) -> lines {2}" -f $code, $hits.Count, (($hits | ForEach-Object LineNumber) -join ','))
}
$recon = Join-Path $Root 'docs/plans/2026-11-10-federation-reconciliation.md'
$r7 = Select-String -Path $recon -SimpleMatch -Pattern '99'
Write-Host ("  reconciliation.md '99' occurrences: {0} -> lines {1}" -f $r7.Count, (($r7 | ForEach-Object LineNumber) -join ','))
$r7b = Select-String -Path $recon -SimpleMatch -Pattern '91 current'
Write-Host ("  reconciliation.md '91 current' occurrences: {0}" -f $r7b.Count)

Write-Host ''
Write-Host 'DONE.'

